package id.kemkes.satusehat;
import java.sql.*;import java.time.Instant;import java.util.*;
final class SQLiteQueue implements AutoCloseable {record Event(String eventId,String operation,String resourceType,String resourceId,String payloadJson,int attempt){}private final Connection db;SQLiteQueue(String path)throws Exception{Class.forName("org.sqlite.JDBC");db=DriverManager.getConnection("jdbc:sqlite:"+path);try(var s=db.createStatement()){s.execute("PRAGMA journal_mode=WAL");s.execute("CREATE TABLE IF NOT EXISTS integration_events(event_id TEXT PRIMARY KEY,organization_id TEXT NOT NULL,operation TEXT NOT NULL,resource_type TEXT NOT NULL,resource_id TEXT,payload_json TEXT,status TEXT NOT NULL,attempt INTEGER NOT NULL DEFAULT 0,http_status INTEGER,error_category TEXT,error_message TEXT,created_at TEXT NOT NULL,updated_at TEXT NOT NULL,next_retry_at TEXT)");s.execute("CREATE INDEX IF NOT EXISTS idx_integration_events_ready ON integration_events(status,next_retry_at,created_at)");}}String enqueue(String org,String op,String rt,String id,String payload)throws Exception{op=op.toUpperCase();if(!Set.of("GET","POST","PUT","PATCH").contains(op))throw new IllegalArgumentException("unsupported operation");if(Set.of("PUT","PATCH").contains(op)&&(id==null||id.isBlank()))throw new IllegalArgumentException("resourceId required for PUT/PATCH");String eid=UUID.randomUUID().toString(),n=Instant.now().toString();try(var p=db.prepareStatement("INSERT INTO integration_events(event_id,organization_id,operation,resource_type,resource_id,payload_json,status,attempt,created_at,updated_at)VALUES(?,?,?,?,?,?,?,0,?,?)")){p.setString(1,eid);p.setString(2,org);p.setString(3,op);p.setString(4,rt);p.setString(5,id);p.setString(6,payload);p.setString(7,EventStatus.QUEUED.name());p.setString(8,n);p.setString(9,n);p.executeUpdate();}return eid;}List<Event> ready(int limit)throws Exception{var out=new ArrayList<Event>();try(var p=db.prepareStatement("SELECT event_id,operation,resource_type,resource_id,payload_json,attempt FROM integration_events WHERE status IN ('QUEUED','RETRYING','RATE_LIMITED') AND (next_retry_at IS NULL OR next_retry_at<=?) ORDER BY created_at LIMIT ?")){p.setString(1,Instant.now().toString());p.setInt(2,limit);try(var r=p.executeQuery()){while(r.next())out.add(new Event(r.getString(1),r.getString(2),r.getString(3),r.getString(4),r.getString(5),r.getInt(6)));}}return out;}int markProcessing(String id)throws Exception{try(var p=db.prepareStatement("UPDATE integration_events SET status='PROCESSING',attempt=attempt+1,updated_at=? WHERE event_id=?")){p.setString(1,Instant.now().toString());p.setString(2,id);p.executeUpdate();}try(var p=db.prepareStatement("SELECT attempt FROM integration_events WHERE event_id=?")){p.setString(1,id);try(var r=p.executeQuery()){r.next();return r.getInt(1);}}}void complete(String id,EventStatus status,Integer http,String cat,String msg,String next)throws Exception{if(msg!=null&&msg.length()>2000)msg=msg.substring(0,2000);try(var p=db.prepareStatement("UPDATE integration_events SET status=?,http_status=?,error_category=?,error_message=?,updated_at=?,next_retry_at=? WHERE event_id=?")){p.setString(1,status.name());if(http==null)p.setNull(2,Types.INTEGER);else p.setInt(2,http);p.setString(3,cat);p.setString(4,msg);p.setString(5,Instant.now().toString());p.setString(6,next);p.setString(7,id);p.executeUpdate();}}public void close()throws Exception{db.close();}}
